const body = $input.first().json.body;

const report = body.report;
const goals = body.goals || [];
const entries = body.entries || [];

// Build a structured prompt with all the data
let prompt = `You are a performance management expert. Generate a concise, insightful summary for a team member's performance review.\n\n`;
prompt += `## Team Member: ${report.firstName} ${report.lastName}\n\n`;

// Goals section
if (goals.length > 0) {
  prompt += `## Development Goals\n`;
  goals.forEach((goal, i) => {
    prompt += `${i + 1}. **${goal.title}**`;
    if (goal.description) prompt += ` - ${goal.description}`;
    prompt += `\n`;
  });
  prompt += `\n`;
}

// Entries section grouped by type
const entryTypes = {
  feedback: 'Feedback',
  accomplishment: 'Accomplishments',
  kudos: 'Kudos',
  notes: 'Notes',
  career_conversation: 'Career Conversations',
  third_party_feedback: 'Third-Party Feedback'
};

for (const [type, label] of Object.entries(entryTypes)) {
  const typeEntries = entries.filter(e => e.entryType === type);
  if (typeEntries.length === 0) continue;

  prompt += `## ${label} (${typeEntries.length})\n`;
  typeEntries.forEach((entry, i) => {
    prompt += `### Entry ${i + 1}`;
    if (entry.title) prompt += `: ${entry.title}`;
    prompt += `\n`;

    if (entry.feedbackType) prompt += `- Type: ${entry.feedbackType}\n`;
    if (entry.feedbackGiven !== null) prompt += `- Feedback delivered: ${entry.feedbackGiven ? 'Yes' : 'No'}\n`;
    if (entry.situation) prompt += `- Situation: ${entry.situation}\n`;
    if (entry.behavior) prompt += `- Behavior: ${entry.behavior}\n`;
    if (entry.impact) prompt += `- Impact: ${entry.impact}\n`;
    if (entry.notes) prompt += `- Notes: ${entry.notes}\n`;
    if (entry.providerName) prompt += `- Provider: ${entry.providerName}\n`;
    if (entry.linkedGoals && entry.linkedGoals.length > 0) {
      prompt += `- Linked Goals: ${entry.linkedGoals.join(', ')}\n`;
    }
    prompt += `\n`;
  });
}

prompt += `---\n\n`;
prompt += `Based on all the above entries and goals, write a performance summary in markdown format. Include:\n`;
prompt += `1. **Overall Performance** - A brief overall assessment (2-3 sentences)\n`;
prompt += `2. **Key Strengths** - Top strengths demonstrated across entries\n`;
prompt += `3. **Areas for Growth** - Areas where improvement was noted or constructive feedback was given\n`;
prompt += `4. **Goal Progress** - How entries relate to their development goals (if goals exist)\n`;
prompt += `5. **Recommendations** - Actionable next steps\n\n`;
prompt += `Keep the summary concise (300-500 words). Use bullet points. Be specific, referencing actual entries where relevant. Do not include a title heading - start directly with the content.`;

return [{ json: { prompt } }];

